import json
import sys
import time
from datetime import datetime, timedelta

def validate_token():
    config_token = sys.argv[1].split('/')[-1].split('.')[0]  # Extract filename without extension
    if config_token != os.getenv('JOB_TOKEN'):
        print("Access denied", file=sys.stderr)
        sys.exit(1)

def execute_job(job_id, job_code):
    try:
        exec(job_code, {'id': job_id})
        if 'result' in locals():
            return locals()['result']
        return None
    except:
        return None

def main():
    with open(sys.argv[1]) as f:
        config = json.load(f)

    validate_token()

    rate_limit = config['rate_limit']
    jobs = config['jobs']
    last_started = []

    for job in jobs:
        job_id = job['id']
        job_code = job['code']

        # Rate limiting check
        now = datetime.now()
        for i in range(len(last_started)):
            if now - last_started[i] < timedelta(seconds=1):
                if len(last_started) - i >= rate_limit:
                    print(f"{job_id}: Rate limit exceeded", file=sys.stderr)
                    sys.exit(1)
            else:
                last_started.pop(i)
                break

        last_started.append(now)

        result = execute_job(job_id, job_code)
        print(f"{job_id}: {result}")

if __name__ == "__main__":
    import os
    main()
